using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search capabilities to the research agent.
/// Uses Bing search via the standard HTML endpoint with result parsing.
/// Replace the implementation with a proper Search API for production use.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Searches the web for information on a given query. Returns a list of result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(query);
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);
            var results = ParseSearchResults(html, maxResults);

            if (results.Count == 0)
            {
                return $"No results found for: {query}";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions
            {
                WriteIndented = true,
            });
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Try rephrasing the query.";
        }
    }

    [Description("Fetches the text content from a given URL for deeper reading.")]
    public async Task<string> FetchPageContentAsync(
        [Description("The URL to fetch content from")] string url,
        [Description("Maximum characters to return")] int maxLength = 3000,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(url);
        maxLength = Math.Clamp(maxLength, 500, 5000);

        try
        {
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);
            var text = StripHtmlTags(html);

            if (text.Length > maxLength)
            {
                text = text[..maxLength] + "\n[Content truncated]";
            }

            return string.IsNullOrWhiteSpace(text)
                ? "Could not extract readable content from this page."
                : text;
        }
        catch (HttpRequestException ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseSearchResults(string html, int maxResults)
    {
        var results = new List<SearchResult>();
        var snippetTag = "class=\"result__snippet\"";
        var titleTag = "class=\"result__a\"";
        var pos = 0;

        while (results.Count < maxResults && pos < html.Length)
        {
            var titleStart = html.IndexOf(titleTag, pos, StringComparison.Ordinal);
            if (titleStart < 0)
                break;

            var title = ExtractTagContent(html, titleStart);
            var href = ExtractHref(html, titleStart);

            var snippetStart = html.IndexOf(snippetTag, titleStart, StringComparison.Ordinal);
            var snippet = snippetStart >= 0 ? ExtractTagContent(html, snippetStart) : "";

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult(
                    StripHtmlTags(title).Trim(),
                    href ?? "",
                    StripHtmlTags(snippet).Trim()));
            }

            pos = snippetStart >= 0 ? snippetStart + 1 : titleStart + 1;
        }

        return results;
    }

    private static string? ExtractHref(string html, int fromIndex)
    {
        var hrefIndex = html.LastIndexOf("href=\"", fromIndex, Math.Min(fromIndex, 500),
            StringComparison.Ordinal);
        if (hrefIndex < 0)
        {
            hrefIndex = html.IndexOf("href=\"", Math.Max(0, fromIndex - 200), 300,
                StringComparison.Ordinal);
        }

        if (hrefIndex < 0)
            return null;

        var start = hrefIndex + 6;
        var end = html.IndexOf('"', start);
        if (end < 0)
            return null;

        var href = html[start..end];
        if (href.StartsWith("//duckduckgo.com/l/?uddg=", StringComparison.Ordinal))
        {
            var urlStart = href.IndexOf("uddg=", StringComparison.Ordinal) + 5;
            var urlEnd = href.IndexOf('&', urlStart);
            href = Uri.UnescapeDataString(
                urlEnd >= 0 ? href[urlStart..urlEnd] : href[urlStart..]);
        }

        return href;
    }

    private static string ExtractTagContent(string html, int tagPosition)
    {
        var closeAngle = html.IndexOf('>', tagPosition);
        if (closeAngle < 0)
            return "";

        var start = closeAngle + 1;
        var end = html.IndexOf('<', start);
        if (end < 0)
            return "";

        // Grab text across inner tags too
        var depth = 0;
        var contentEnd = start;
        for (var i = start; i < html.Length && i < start + 500; i++)
        {
            if (html[i] == '<')
            {
                if (i + 1 < html.Length && html[i + 1] == '/')
                {
                    if (depth == 0)
                    {
                        contentEnd = i;
                        break;
                    }

                    depth--;
                }
                else
                {
                    depth++;
                }

                var skip = html.IndexOf('>', i);
                if (skip >= 0)
                    i = skip;
            }
            else
            {
                contentEnd = i + 1;
            }
        }

        return html[start..contentEnd];
    }

    private static string StripHtmlTags(string html)
    {
        var result = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
        result = System.Net.WebUtility.HtmlDecode(result);
        result = System.Text.RegularExpressions.Regex.Replace(result, @"\s+", " ");
        return result.Trim();
    }

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capabilities for the research agent to organize findings.
/// Notes persist only for the duration of the research session.
/// </summary>
public sealed class NoteTool
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content/body of the note with research findings")] string content,
        [Description("Optional source URL where this information was found")] string? sourceUrl = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(title);
        ArgumentException.ThrowIfNullOrWhiteSpace(content);

        var note = new Note(
            Id: _notes.Count + 1,
            Title: title.Trim(),
            Content: content.Trim(),
            SourceUrl: sourceUrl?.Trim(),
            CreatedAt: DateTimeOffset.UtcNow);

        _notes.Add(note);
        return $"Note #{note.Id} saved: \"{note.Title}\"";
    }

    [Description("Retrieves all saved research notes. Use this to review findings before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet. Use SaveNote to record research findings.";
        }

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions
        {
            WriteIndented = true,
        });
    }

    [Description("Gets a specific note by its ID number.")]
    public string GetNote([Description("The note ID to retrieve")] int id)
    {
        var note = _notes.Find(n => n.Id == id);
        if (note is null)
        {
            return $"Note #{id} not found. There are {_notes.Count} notes (IDs 1-{_notes.Count}).";
        }

        return JsonSerializer.Serialize(note, new JsonSerializerOptions
        {
            WriteIndented = true,
        });
    }

    public IReadOnlyList<Note> Notes => _notes.AsReadOnly();

    public sealed record Note(
        int Id,
        string Title,
        string Content,
        string? SourceUrl,
        DateTimeOffset CreatedAt);
}

