using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

// Configure OpenAI — set your API key via environment variable or user-secrets:
//   export OPENAI_API_KEY=sk-...
//   (or: dotnet user-secrets set "AI:ApiKey" "sk-...")
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddHttpClient<WebSearchTool>();
builder.Services.AddSingleton<NoteTool>();
builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, apiKey));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearch = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTool>();

// Register tools from the tool classes
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(webSearch.FetchPageContentAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetAllNotes),
    AIFunctionFactory.Create(noteTool.GetNote),
};

// Create the agent with the chat client and tools
var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your job is to thoroughly research a topic using web search
    and produce a well-organized summary.

    Follow this process:
    1. Search the web for the topic using multiple queries to get broad coverage.
    2. Fetch page content from the most relevant results for deeper information.
    3. Save important findings as notes, including source URLs.
    4. After gathering enough information, review all your notes.
    5. Produce a final comprehensive summary organized with clear headings,
       key facts, and source citations.

    Be thorough but efficient — aim for 3-5 searches and save at least 3 notes
    before summarizing. Always cite your sources.
    """);

// Get the research topic from the user
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent                 ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  I'll research any topic and summarize   ║");
Console.WriteLine("║  findings from the web.                  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine("This may take a minute...\n");

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
    Tools = [.. tools],
};

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

// Stream the agent's work so the user can see progress
Console.ForegroundColor = ConsoleColor.DarkGray;
await foreach (var message in agent.InvokeStreamingAsync(history, chatOptions, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.ResetColor();
        Console.Write(message.Text);
    }
    else if (message.Role == ChatRole.Tool)
    {
        Console.ForegroundColor = ConsoleColor.DarkGray;
        // Show tool activity without dumping full content
        var toolName = message.AuthorName ?? "tool";
        Console.WriteLine($"  [🔧 {toolName} called]");
    }
}

Console.ResetColor();
Console.WriteLine();

// Show collected notes summary
if (noteTool.Notes.Count > 0)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.WriteLine($"\n📝 {noteTool.Notes.Count} research note(s) were collected during this session.");
    Console.ResetColor();
}
