+    public async Task<string> FetchPageContentAsync(
+        [Description("The URL to fetch content from")] string url,
+        [Description("Maximum characters to return")] int maxLength = 3000,
+        CancellationToken cancellationToken = default)
+    {
+        ArgumentException.ThrowIfNullOrWhiteSpace(url);
+        maxLength = Math.Clamp(maxLength, 500, 5000);
+
+        try
+        {
+            var request = new HttpRequestMessage(HttpMethod.Get, url);
+            request.Headers.UserAgent.ParseAdd(
+                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
+
+            var response = await _httpClient.SendAsync(request, cancellationToken);
+            response.EnsureSuccessStatusCode();
+
+            var html = await response.Content.ReadAsStringAsync(cancellationToken);
+            var text = StripHtmlTags(html);
+
+            if (text.Length > maxLength)
+            {
+                text = text[..maxLength] + "\n[Content truncated]";
+            }
+
+            return string.IsNullOrWhiteSpace(text)
+                ? "Could not extract readable content from this page."
+                : text;
+        }
+        catch (HttpRequestException ex)
+        {
+            return $"Failed to fetch page: {ex.Message}";
+        }
