+    {
+        var hrefIndex = html.LastIndexOf("href=\"", fromIndex, Math.Min(fromIndex, 500),
+            StringComparison.Ordinal);
+        if (hrefIndex < 0)
+        {
+            hrefIndex = html.IndexOf("href=\"", Math.Max(0, fromIndex - 200), 300,
+                StringComparison.Ordinal);
+        }
+
+        if (hrefIndex < 0)
+            return null;
+
+        var start = hrefIndex + 6;
+        var end = html.IndexOf('"', start);
+        if (end < 0)
+            return null;
+
+        var href = html[start..end];
+        if (href.StartsWith("//duckduckgo.com/l/?uddg=", StringComparison.Ordinal))
+        {
+            var urlStart = href.IndexOf("uddg=", StringComparison.Ordinal) + 5;
+            var urlEnd = href.IndexOf('&', urlStart);
+            href = Uri.UnescapeDataString(
+                urlEnd >= 0 ? href[urlStart..urlEnd] : href[urlStart..]);
+        }
+
+        return href;
+    }
+
+    private static string ExtractTagContent(string html, int tagPosition)
+    {
+        var closeAngle = html.IndexOf('>', tagPosition);
+        if (closeAngle < 0)
+            return "";
+
+        var start = closeAngle + 1;
+        var end = html.IndexOf('<', start);
+        if (end < 0)
+            return "";
+
+        // Grab text across inner tags too
+        var depth = 0;
+        var contentEnd = start;
+        for (var i = start; i < html.Length && i < start + 500; i++)
+        {
+            if (html[i] == '<')
+            {
+                if (i + 1 < html.Length && html[i + 1] == '/')
+                {
+                    if (depth == 0)
+                    {
+                        contentEnd = i;
+                        break;
+                    }
+
+                    depth--;
+                }
+                else
+                {
+                    depth++;
+                }
+
+                var skip = html.IndexOf('>', i);
+                if (skip >= 0)
+                    i = skip;
+            }
+            else
+            {
+                contentEnd = i + 1;
+            }
+        }
